"""Verifier boundary tests only; generated bytes are not Android build proof."""
import hashlib
import importlib.util
from pathlib import Path
import struct
import os
import time
import tempfile
import unittest
import zipfile

SOURCE = Path(__file__).resolve().parents[1] / "build_hardcore_android_templates.py"
SPEC = importlib.util.spec_from_file_location("native_template_builder", SOURCE)
BUILDER = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(BUILDER)


class ArtifactBoundaries(unittest.TestCase):
    def test_elf_architecture_and_native_fingerprint(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "parser_fixture.so"
            header = bytearray(64)
            header[:6] = b"\x7fELF\x02\x01"
            struct.pack_into("<H", header, 18, 183)
            path.write_bytes(header + b"a" * 64)
            self.assertEqual(BUILDER.verify_elf(path, 183, "a" * 64)["sha256"], BUILDER.sha(path))
            with self.assertRaisesRegex(RuntimeError, "fingerprint absent"):
                BUILDER.verify_elf(path, 183, "b" * 64)
            with self.assertRaisesRegex(RuntimeError, "architecture"):
                BUILDER.verify_elf(path, 62, None)
            header[5] = 2
            path.write_bytes(header + b"a" * 64)
            with self.assertRaisesRegex(RuntimeError, "architecture"):
                BUILDER.verify_elf(path, 183, None)

    def test_apk_abi_set_and_exact_jni_bytes(self):
        expected = {}
        for abi in ("arm64-v8a", "x86_64"):
            expected[abi] = {name: {"sha256": hashlib.sha256((abi + name).encode()).hexdigest()}
                             for name in ("libgodot_android.so", "libc++_shared.so")}
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "verifier_only_fixture.apk"
            def write(extra_abi=False, wrong_bytes=False):
                with zipfile.ZipFile(path, "w") as archive:
                    for abi, files in expected.items():
                        for name in files:
                            payload = (abi + name).encode()
                            if wrong_bytes and abi == "x86_64":
                                payload += b"stale"
                            archive.writestr("lib/" + abi + "/" + name, payload)
                    if extra_abi:
                        archive.writestr("lib/armeabi-v7a/libgodot_android.so", b"old")
            write()
            self.assertEqual(set(BUILDER.verify_jni_zip(path, expected, "lib")), set(expected))
            write(wrong_bytes=True)
            with self.assertRaisesRegex(RuntimeError, "differs"):
                BUILDER.verify_jni_zip(path, expected, "lib")
            write(extra_abi=True)
            with self.assertRaisesRegex(RuntimeError, "ABI set"):
                BUILDER.verify_jni_zip(path, expected, "lib")
            with zipfile.ZipFile(path, "w") as archive:
                archive.writestr("unrelated.txt", "no JNI")
            with self.assertRaisesRegex(RuntimeError, "ABI set"):
                BUILDER.verify_jni_zip(path, expected, "lib")

    def test_compile_identity_option_is_exact_and_module_local(self):
        expected = "hardcore_native_source_sha256=" + "0a" * 32
        self.assertEqual(BUILDER.native_define("0a" * 32), expected)
        for invalid in ("", "a" * 63, "A" * 64, "a" * 64 + " suffix", "../" + "a" * 61):
            with self.assertRaisesRegex(RuntimeError, "full lowercase"):
                BUILDER.native_define(invalid)
        for target in ("debug", "release"):
            for arch in BUILDER.ARCHES:
                argv = BUILDER.scons_command(Path("scons.exe"), Path("engine"), {"precision":"single"}, "0a" * 32, target, arch, 2)
                self.assertEqual(argv.count(expected), 1)
                self.assertFalse(any(arg.startswith("cppdefines=") for arg in argv))
                self.assertIn("arch=" + arch, argv)
        with self.assertRaisesRegex(RuntimeError, "Unapproved"):
            BUILDER.scons_command(Path("scons"), Path("engine"), {"precision":"single"}, "a" * 64, "debug", "arm32", 1)

    def test_runtime_capability_cannot_be_replaced_by_five_role_seals(self):
        wanted = "a" * 64
        for capability in ({}, {"native_source_sha256":wanted},
                           {"native_source_identity_injected":False,"native_source_sha256":wanted},
                           {"FEATURE":wanted,"ORIGIN":wanted,"SOURCE":wanted,"WARM":wanted,"WARM_PORT":wanted}):
            with self.assertRaisesRegex(RuntimeError, "not injected"):
                BUILDER.verify_capability(capability, wanted)
        with self.assertRaisesRegex(RuntimeError, "mismatch"):
            BUILDER.verify_capability({"native_source_identity_injected":True,"native_source_sha256":"b" * 64}, wanted)
        self.assertEqual(BUILDER.verify_capability({"native_source_identity_injected":True,"native_source_sha256":wanted}, wanted)["status"], "PASS")

    def test_stale_missing_and_empty_artifacts_never_pass(self):
        with tempfile.TemporaryDirectory() as directory:
            p = Path(directory) / "jni.so"
            started = time.time_ns()
            with self.assertRaisesRegex(RuntimeError, "stale"):
                BUILDER.verify_fresh(p, started)
            p.write_bytes(b"new")
            os.utime(p, ns=(started - 1000000000, started - 1000000000))
            with self.assertRaisesRegex(RuntimeError, "stale"):
                BUILDER.verify_fresh(p, started)
            os.utime(p, ns=(started + 1000000000, started + 1000000000))
            self.assertEqual(BUILDER.verify_fresh(p, started)["bytes"], 3)
            p.write_bytes(b"")
            with self.assertRaisesRegex(RuntimeError, "stale"):
                BUILDER.verify_fresh(p, started)

    def test_duplicate_extra_missing_and_wrong_sized_jni_rejected(self):
        import warnings
        payload = b"actual verifier fixture bytes only"
        expected = {"arm64-v8a":{"libgodot_android.so":{"sha256":hashlib.sha256(payload).hexdigest(),"bytes":len(payload)}}}
        with tempfile.TemporaryDirectory() as directory:
            p = Path(directory) / "parser.aar"
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", UserWarning)
                with zipfile.ZipFile(p,"w") as z:
                    z.writestr("jni/arm64-v8a/libgodot_android.so",payload)
                    z.writestr("jni/arm64-v8a/libgodot_android.so",payload)
            with self.assertRaisesRegex(RuntimeError,"Duplicate"):
                BUILDER.verify_jni_zip(p,expected,"jni")
            with zipfile.ZipFile(p,"w") as z:
                z.writestr("jni/arm64-v8a/libgodot_android.so",payload)
                z.writestr("jni/arm64-v8a/old_unreviewed.so",payload)
            with self.assertRaisesRegex(RuntimeError,"ABI set"):
                BUILDER.verify_jni_zip(p,expected,"jni")
            with zipfile.ZipFile(p,"w") as z:
                z.writestr("jni/arm64-v8a/libgodot_android.so",payload)
            expected["arm64-v8a"]["libgodot_android.so"]["bytes"] += 1
            with self.assertRaisesRegex(RuntimeError,"byte size"):
                BUILDER.verify_jni_zip(p,expected,"jni")
            expected["arm64-v8a"]["libgodot_android.so"]["bytes"] -= 1
            self.assertEqual(BUILDER.verify_jni_zip(p,expected,"jni")["arm64-v8a"]["libgodot_android.so"],hashlib.sha256(payload).hexdigest())

    def test_absent_native_candidate_blocks_preflight(self):
        with tempfile.TemporaryDirectory() as directory:
            root=Path(directory)
            (root/"modules/hardcore_simulation").mkdir(parents=True)
            (root/"modules/hardcore_simulation/simulation_host_original_primitives.cpp").write_text("// unmodified old engine")
            with self.assertRaisesRegex(RuntimeError,"candidate not applied"):
                BUILDER.verify_identity_source(root)


if __name__ == "__main__":
    unittest.main()
